test('invoiceTotals calculates subtotal for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 5,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 0);
  const expectedVAT = Math.round(47500 * 21 / 100);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 47500 + expectedVAT);
});

