test('invoiceTotals includes discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 10,
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  const expectedVAT = Math.round((95000 - 9500) * 21 / 100);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 95000 - 9500 + expectedVAT);
});

test('invoiceTotals calculates discount across multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 10,
      },
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
        discountPercent: 20,
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 42500);
  assert.equal(totals.discount, 9500 + 8500);
  const line1Amount = 95000 - 9500;
  const line2Amount = 42500 - 8500;
  const expectedVAT = Math.round(line1Amount * 21 / 100) + Math.round(line2Amount * 21 / 100);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 137500 - 18000 + expectedVAT);
});

